from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    border = next(value for value in counts if value != background)

    # Find complete rectangular frames of the border color, then fill their
    # background-colored interiors with 4.
    for top in range(h):
        for bottom in range(top + 2, h):
            for left in range(w):
                for right in range(left + 2, w):
                    if (all(grid[top][c] == border and grid[bottom][c] == border
                            for c in range(left, right + 1)) and
                        all(grid[r][left] == border and grid[r][right] == border
                            for r in range(top, bottom + 1))):
                        for r in range(top + 1, bottom):
                            for c in range(left + 1, right):
                                if grid[r][c] == background:
                                    out[r][c] = 4
    return out

